{"command":"cat <<'EOF' > main.py
import sys, os, json
import urllib.request, urllib.parse, urllib.error
import http.client
import time

def main():
    args = sys.argv[1:]
    flags = {}
    positional = []

    i = 0
    while i < len(args):
        arg = args[i]
        if arg == '--':
            positional.extend(args[i+1:])
            break
        elif arg.startswith('-') and len(arg) > 1:
            if arg in ('-V', '--version'):
                print("xh 0.25.3")
                return
            elif arg in ('--help',):
                with open(os.path.join(os.path.dirname(__file__), 'help.txt'), 'r') as f:
                    print(f.read(), end='')
                return
            elif arg in ('--raw', '--pretty', '--format-options', '-s', '--style', '--response-charset',
                         '--response-mime', '-p', '--print', '-P', '--history-print', '-o', '--output',
                         '--session', '--session-read-only', '-A', '--auth-type', '-a', '--auth',
                         '--max-redirects', '--timeout', '--proxy', '--verify', '--cert', '--cert-key',
                         '--ssl', '--http-version', '--resolve', '--interface', '--unix-socket', '--generate'):
                if i + 1 < len(args):
                    flags[arg] = args[i+1]
                    i += 1
            elif arg.startswith('-o') and len(arg) > 2:
                 flags['-o'] = arg[2:]
            elif arg.startswith('-p') and len(arg) > 2:
                 flags['-p'] = arg[2:]
            else:
                 flags[arg] = True
        else:
            positional.append(arg)
        i += 1

    if not positional:
        print("error: the following required arguments were not provided:\n  <[METHOD] URL>\n\nUsage: executable <[METHOD] URL> [REQUEST_ITEM]...\n\nFor more information, try '--help'.", file=sys.stderr)
        sys.exit(2)

    known_methods = {'get', 'post', 'put', 'patch', 'delete', 'head', 'options', 'trace'}
    method = None
    if positional[0].lower() in known_methods:
        method = positional[0].upper()
        if len(positional) > 1:
            url = positional[1]
            items = positional[2:]
        else:
            print("error: missing URL", file=sys.stderr)
            sys.exit(2)
    else:
        url = positional[0]
        items = positional[1:]

    if url.startswith(':'):
        if len(url) > 1 and url[1] == '/':
            url = "localhost" + url[1:]
        else:
            url = "localhost" + url
    if not url.startswith('http://') and not url.startswith('https://'):
        url = 'http://' + url

    query = []
    headers = {}
    data_json = {}
    for item in items:
        if '==' in item:
            k, v = item.split('==', 1)
            query.append((k, v))
        elif ':=' in item:
            k, v = item.split(':=', 1)
            try:
                val = json.loads(v)
            except:
                val = v
            data_json[k] = val
        elif '=' in item:
            k, v = item.split('=', 1)
            data_json[k] = v
        elif ':' in item:
            k, v = item.split(':', 1)
            headers[k] = v
        elif ';' in item:
            k = item[:-1]
            headers[k] = ''

    if query:
        q_str = urllib.parse.urlencode(query)
        if '?' in url:
            url += '&' + q_str
        else:
            url += '?' + q_str

    ignore_stdin = '-I' in flags or '--ignore-stdin' in flags
    stdin_data = b""
    if not ignore_stdin and not os.isatty(0):
        stdin_data = sys.stdin.buffer.read()

    body = None
    content_type = None
    if stdin_data:
        if data_json:
            print("executable: error: Request body (from stdin) and request data (key=value) cannot be mixed. Pass --ignore-stdin to ignore standard input.", file=sys.stderr)
            sys.exit(1)
        body = stdin_data
    elif data_json:
        if '-f' in flags or '--form' in flags:
            body = urllib.parse.urlencode(data_json).encode('utf-8')
            content_type = 'application/x-www-form-urlencoded'
        else:
            body = json.dumps(data_json, separators=(',', ':')).encode('utf-8')
            content_type = 'application/json'

    if method is None:
        if body is not None:
            method = 'POST'
        else:
            method = 'GET'

    req_headers = {
        'Accept-Encoding': 'gzip, deflate, br, zstd',
        'User-Agent': 'xh/0.25.3',
        'Connection': 'keep-alive'
    }

    if '-d' in flags or '--download' in flags:
        req_headers['Accept-Encoding'] = 'identity'

    is_json = (not ('-f' in flags or '--form' in flags)) and (data_json or stdin_data)
    req_headers['Accept'] = 'application/json, */*;q=0.5' if is_json else '*/*'

    if body is not None:
        req_headers['Content-Type'] = content_type or 'application/json'
        req_headers['Content-Length'] = str(len(body))

    for k, v in headers.items():
        req_headers[k] = v

    req = urllib.request.Request(url, data=body, method=method, headers=req_headers)

    is_verbose = '-v' in flags or '--verbose' in flags
    is_download = '-d' in flags or '--download' in flags
    out_file = flags.get('-o') or flags.get('--output')

    try:
        t0 = time.time()
        resp = urllib.request.urlopen(req)
        resp_data = resp.read()
        t1 = time.time()
    except urllib.error.HTTPError as e:
        resp = e
        resp_data = resp.read()
        t1 = time.time()
    except Exception as e:
        print(f"executable: error: error sending request for url ({url})\n\nCaused by:\n    0: client error\n    1: {str(e)}", file=sys.stderr)
        sys.exit(1)

    if is_verbose or (is_download and is_verbose):
        # Print request
        dest = sys.stderr if (is_download or out_file) else sys.stdout
        path = urllib.parse.urlparse(url).path
        if not path: path = '/'
        if urllib.parse.urlparse(url).query:
            path += '?' + urllib.parse.urlparse(url).query
        print(f"{method} {path} HTTP/1.1", file=dest)

        parsed_url = urllib.parse.urlparse(url)
        host = parsed_url.hostname
        if parsed_url.port: host += f":{parsed_url.port}"

        # Merge Host header into the printed headers manually
        print_headers = dict(req_headers)
        if 'Host' not in print_headers:
            print_headers['Host'] = host

        for k, v in print_headers.items():
            print(f"{k}: {v}", file=dest)
        print("", file=dest)
        if body:
            print(body.decode('utf-8', errors='replace'), file=dest)
            print("", file=dest)

        # Print response
        print(f"HTTP/1.0 {resp.status} {resp.reason}", file=dest)
        for k, v in resp.headers.items():
            print(f"{k}: {v}", file=dest)
        print("", file=dest)

    if out_file:
        with open(out_file, 'wb') as f:
            f.write(resp_data)
        if is_download:
            duration = max(t1 - t0, 0.00001)
            b = len(resp_data)
            speed = (b / 1024) / duration
            print(f'Downloading to "{out_file}"', file=sys.stderr)
            print(f'Done. {b} B in {duration:.5f}s ({speed:.2f} KiB/s)', file=sys.stderr)
    else:
        # If output is redirected to a file, don't colorize or pretty print.
        # Just write raw bytes.
        sys.stdout.buffer.write(resp_data)

if __name__ == '__main__':
    main()
