    elif '-m' in flags or '--meta' in flags:
        print_opts = "m"
    elif '-p' in flags:
        print_opts = flags['-p']
    else:
        if os.isatty(1) and not is_download and not out_file:
            print_opts = "hb"
        else:
            print_opts = "b"

    if is_download and is_verbose:
        print_opts = "Hh"
    elif out_file and is_verbose:
        print_opts = "Hh"

    dest = sys.stderr if (is_download or out_file) else sys.stdout

    if "H" in print_opts:
        path = urllib.parse.urlparse(url).path or '/'
        if urllib.parse.urlparse(url).query:
            path += '?' + urllib.parse.urlparse(url).query
        print(f"{method} {path} HTTP/1.1", file=dest)

        parsed_url = urllib.parse.urlparse(url)
        host = parsed_url.hostname
        if parsed_url.port: host += f":{parsed_url.port}"

        print_headers = dict(req_headers)
        if 'Host' not in print_headers:
            print_headers['Host'] = host

        for k, v in print_headers.items():
            print(f"{k}: {v}", file=dest)
        print("", file=dest)

    if "B" in print_opts and body:
        print(body.decode('utf-8', errors='replace'), file=dest)
        print("", file=dest)

    if "h" in print_opts:
        version_str = "HTTP/1.1" if getattr(resp, 'version', 10) == 11 else "HTTP/1.0"
        print(f"{version_str} {resp.status} {resp.reason}", file=dest)
        for k, v in resp.headers.items():
            k = "-".join(word.capitalize() for word in k.split("-"))
            print(f"{k}: {v}", file=dest)
        print("", file=dest)

    if out_file:
        with open(out_file, 'wb') as f:
            f.write(resp_data)
        if is_download:
            duration = max(t1 - t0, 0.00001)
            b = len(resp_data)
            speed = (b / 1024) / duration
            print(f'Downloading to "{out_file}"', file=sys.stderr)
            print(f'Done. {b} B in {duration:.5f}s ({speed:.2f} KiB/s)', file=sys.stderr)
    elif "b" in print_opts:
        if dest == sys.stdout:
            sys.stdout.flush()
            sys.stdout.buffer.write(resp_data)
        else:
            dest.flush()
            dest.buffer.write(resp_data)

if __name__ == '__main__':
    main()
